<script setup lang="ts">
import Modal from "@papilio/ui/Modal.vue";
import { computed, onUnmounted, ref, watch } from "vue";
import { useAuth } from "@papilio/auth";
import { item, query, request, type Page, type NotificationRecord, type NotificationAvailability, type NotificationAttempt, type NotificationRecovery } from "@papilio/api";
import { faDate, faNumber, toman } from "@papilio/ui";
import { kinds, outcomes, statuses } from "./labels";
const props=defineProps<{audience:"admin"|"customer";customerId?:number}>();
const auth=useAuth();const prefix=computed(()=>`/v1/${props.audience}/notifications`);
const observedKinds=ref<NotificationRecord["kind"][]>([]);
const rows=ref<NotificationRecord[]>([]);const selected=ref<NotificationRecord|null>(null);const policy=ref<NotificationAvailability|null>(null);
const q=ref("");const kind=ref("");const status=ref("");const read=ref("");const page=ref(1);const pages=ref(1);const total=ref(0);
const loading=ref(false);const selecting=ref(false);const busy=ref(false);const error=ref("");const notice=ref("");const auditError=ref("");const auditLoading=ref(false);
const attempts=ref<NotificationAttempt[]>([]);const history=ref<NotificationRecovery[]>([]);const attemptPage=ref(1);const attemptPages=ref(1);const historyPage=ref(1);const historyPages=ref(1);
const title=ref("");const body=ref("");const draftCustomer=ref<number|undefined>();const key=ref(crypto.randomUUID());const reason=ref("");const action=ref<"retry"|"cancel">("retry");
let listVersion=0;let selectionVersion=0;let auditVersion=0;
const knownCustomer=computed(()=>props.customerId??selected.value?.customer_id);
const mayCreate=computed(()=>props.audience==="admin"&&auth.can("notifications","create")&&policy.value?.capacity_valid&&policy.value.enabled&&policy.value.templates.manual.enabled);
const mayRecover=computed(()=>props.audience==="admin"&&auth.can("notifications","update")&&selected.value?.revision!==undefined&&["pending","retry","ambiguous","failed"].includes(selected.value?.status??""));
const visibleKinds=computed(()=>Object.fromEntries(Object.entries(kinds).filter(([value])=>!value.startsWith("checkout_")||policy.value?.supported_kinds?.includes(value as NotificationRecord["kind"])||observedKinds.value.includes(value as NotificationRecord["kind"]))));
const messageSize=computed(()=>Array.from(title.value+"\n"+body.value).length);
const validDraft=computed(()=>title.value.trim()&&body.value.trim()&&Array.from(title.value).length<=160&&policy.value&&messageSize.value<=policy.value.max_message_chars);
function fail(cause:unknown):string{return cause instanceof Error?cause.message:"The operation failed. Please try again.";}
async function load():Promise<void>{const stamp=++listVersion;loading.value=true;error.value="";try{const result=await request<Page<NotificationRecord>>(`${prefix.value}?${query({q:q.value,kind:kind.value||undefined,is_read:read.value?read.value==="read":undefined,status:props.audience==="admin"?status.value||undefined:undefined,customer_id:props.audience==="admin"?props.customerId:undefined,page:page.value})}`);const settings=props.audience==="admin"?await item<NotificationAvailability>(`${prefix.value}/policy`):null;if(stamp!==listVersion)return;observedKinds.value=[...new Set([...observedKinds.value,...result.data.map(row=>row.kind)])];rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;total.value=result.meta.pager?.total_items??0;policy.value=settings;}catch(cause){if(stamp===listVersion)error.value=fail(cause);}finally{if(stamp===listVersion)loading.value=false;}}
async function audit():Promise<void>{const row=selected.value;if(!row||props.audience!=="admin")return;const stamp=++auditVersion;auditLoading.value=true;auditError.value="";try{const [a,h]=await Promise.all([request<Page<NotificationAttempt>>(`${prefix.value}/${row.id}/attempts?${query({page:attemptPage.value})}`),request<Page<NotificationRecovery>>(`${prefix.value}/${row.id}/history?${query({page:historyPage.value})}`)]);if(stamp!==auditVersion||selected.value?.id!==row.id)return;attempts.value=a.data;attemptPages.value=a.meta.pager?.total_pages??1;history.value=h.data;historyPages.value=h.meta.pager?.total_pages??1;}catch(cause){if(stamp===auditVersion)auditError.value=fail(cause);}finally{if(stamp===auditVersion)auditLoading.value=false;}}
async function select(row:NotificationRecord,preserve=false):Promise<void>{if(busy.value||selecting.value)return;const stamp=++selectionVersion;selecting.value=true;error.value="";try{const fresh=await item<NotificationRecord>(`${prefix.value}/${row.id}`);if(stamp!==selectionVersion)return;selected.value=fresh;if(!preserve){reason.value="";action.value="retry";attemptPage.value=1;historyPage.value=1;attempts.value=[];history.value=[];}if(props.audience==="admin")void audit();if(preserve)notice.value="Current notification loaded. Your recovery draft is retained.";}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{if(stamp===selectionVersion)selecting.value=false;}}
const createOpen=ref(false);
function startDraft():void{if(busy.value||!mayCreate.value||knownCustomer.value===undefined)return;if(draftCustomer.value===undefined){draftCustomer.value=knownCustomer.value;title.value=policy.value!.templates.manual.title;body.value=policy.value!.templates.manual.body;key.value=crypto.randomUUID();}createOpen.value=true;}
async function create():Promise<void>{if(busy.value||!mayCreate.value||draftCustomer.value===undefined||!validDraft.value)return;const stamp=selectionVersion;busy.value=true;error.value="";notice.value="";try{const result=await item<NotificationRecord>(prefix.value,"POST",{customer_id:draftCustomer.value,request_key:key.value,title:title.value,body:body.value});if(stamp!==selectionVersion)return;selected.value=result;title.value="";body.value="";draftCustomer.value=undefined;key.value=crypto.randomUUID();createOpen.value=false;notice.value="Notification created. Track delivery from its record.";await load();void audit();}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{busy.value=false;}}
async function setRead():Promise<void>{const row=selected.value;if(props.audience!=="customer"||!row||busy.value)return;const stamp=selectionVersion;busy.value=true;error.value="";try{const result=await item<NotificationRecord>(`${prefix.value}/${row.id}/read`,"PUT",{is_read:!row.is_read});if(stamp!==selectionVersion)return;selected.value=result;await load();}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{busy.value=false;}}
async function recover():Promise<void>{const row=selected.value;if(!row||!mayRecover.value||busy.value)return;const stamp=selectionVersion;busy.value=true;error.value="";notice.value="";try{const result=await item<NotificationRecord>(`${prefix.value}/${row.id}/recovery`,"PUT",{expected_revision:row.revision,action:action.value,reason:reason.value});if(stamp!==selectionVersion)return;selected.value=result;reason.value="";notice.value="Recovery decision recorded.";await load();void audit();}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{busy.value=false;}}
async function dispatch():Promise<void>{const row=selected.value;if(!row||busy.value||!auth.can("notifications","update"))return;const stamp=selectionVersion;busy.value=true;error.value="";notice.value="";try{await item(`${prefix.value}/${row.id}/dispatch`,"POST");if(stamp===selectionVersion)notice.value="Delivery check queued. Delivery is not confirmed yet.";}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{busy.value=false;}}
const sourceLink=computed(()=>{const row=selected.value;if(!row||row.record_id===null)return null;if(["checkout_action_required","checkout_cancelled","checkout_expired"].includes(row.kind)&&props.audience==="customer")return {path:"/account",query:{checkout_id:row.record_id}};if(row.kind==="support_reply"&&(props.audience==="customer"||auth.can("support")))return {path:props.audience==="customer"?"/account/support":"/support",query:{ticket_id:row.record_id,...(props.audience==="admin"?{customer_id:row.customer_id}:{})}};if(row.kind==="payment_approved"&&(props.audience==="customer"||auth.can("payments")))return {path:props.audience==="customer"?"/account":"/payments",query:{topup_id:row.record_id}};if(["expiry_soon","renewal_unfunded","provisioning_failed","subscription_active","tier_changed","discount_applied","volume_low","renewal_available"].includes(row.kind)&&(props.audience==="customer"||auth.can("subscriptions")))return {path:props.audience==="customer"?"/account":"/subscriptions",query:{subscription_id:row.record_id}};return null;});
watch([q,kind,status,read],()=>{page.value=1;void load();});
watch(()=>[props.audience,props.customerId],()=>{selectionVersion++;auditVersion++;observedKinds.value=[];selected.value=null;createOpen.value=false;draftCustomer.value=undefined;title.value="";body.value="";key.value=crypto.randomUUID();page.value=1;void load();},{immediate:true});
onUnmounted(()=>{listVersion++;selectionVersion++;auditVersion++;});
</script>
<template><div class="stack"><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message success" role="status">{{notice}}</p><p v-if="policy&&!policy.capacity_valid" class="hint-box">Notification policy exceeds current capacity. An operator must update the settings.</p><p v-if="policy&&!policy.outbound_available" class="hint-box">External delivery is disabled. Customer inbox and history remain available.</p><div :class="{split:!!selected}"><section class="card card-pad"><h2>Notifications</h2><div class="form-grid"><label class="field"><span>Search notification title</span><input v-model="q" :disabled="busy" /></label><label class="field"><span>Notification type</span><select v-model="kind" aria-label="Notification type" :disabled="busy"><option value="">All</option><option v-for="(label,value) in visibleKinds" :key="value" :value="value">{{label}}</option></select></label><label class="field"><span>Read status</span><select v-model="read" aria-label="Read status" :disabled="busy"><option value="">All</option><option value="unread">Unread</option><option value="read">Read</option></select></label><label v-if="audience==='admin'" class="field"><span>Delivery status</span><select v-model="status" aria-label="Delivery status" :disabled="busy"><option value="">All</option><option v-for="(label,value) in statuses" :key="value" :value="value">{{label}}</option></select></label><button class="btn secondary" :disabled="loading||busy" @click="load">Refresh notifications</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th v-if="audience==='admin'">Customer</th><th>Status</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" tabindex="0" :class="{'selected-row':selected?.id===row.id}" @click="select(row)" @keydown.enter="select(row)"><td>{{row.title}} · {{faNumber(row.id)}}</td><td v-if="audience==='admin'&&row.customer_id!==undefined">{{faNumber(row.customer_id)}}</td><td>{{audience==='admin'&&row.status?statuses[row.status]:row.is_read?'Read':'Unread'}}</td></tr></tbody></table></div><p v-if="loading">Loading…</p><p v-else-if="!rows.length&&!error">No notifications found.</p><div class="pager"><button :disabled="page<=1||loading||busy" @click="page--;load()">‹</button><span>{{faNumber(page)}} · {{faNumber(total)}} notifications</span><button :disabled="page>=pages||loading||busy" @click="page++;load()">›</button></div></section>
<section v-if="selected" class="card card-pad stack"><h2>{{selected.title}}</h2><p>{{faDate(selected.created_at)}} · {{kinds[selected.kind]}}</p><p class="notification-body">{{selected.body}}</p><section v-if="selected.subscription_context" class="hint-box" aria-label="Captured subscription alert"><h3>At notice creation</h3><p>{{faDate(selected.subscription_context.captured_at)}} · Generation {{selected.subscription_context.generation}} · Rule {{selected.subscription_context.threshold_code}}</p><p>Used: {{faNumber(selected.subscription_context.used_bytes/1024**3)}} GiB · Remaining: {{selected.subscription_context.remaining_bytes===null?"Unlimited":faNumber(selected.subscription_context.remaining_bytes/1024**3)+" GiB"}}</p><p>Expiry: {{selected.subscription_context.expires_at?faDate(selected.subscription_context.expires_at):"No expiry"}} · Renewal price: {{selected.subscription_context.renewal_price_rial===null?"Unavailable":toman(selected.subscription_context.renewal_price_rial)}}</p><p>Open the related service for current state and renewal readiness.</p></section><RouterLink v-if="sourceLink" class="btn secondary" :to="sourceLink">Related record</RouterLink><button v-if="audience==='customer'" class="btn secondary" :disabled="busy||selecting" @click="setRead">{{selected.is_read?'Mark unread':'Mark read'}}</button><template v-else><p v-if="selected.created_by_staff_id!=null">Created by staff: {{faNumber(selected.created_by_staff_id)}}</p><p v-else>Automatic system notification</p><p v-if="selected.status">{{statuses[selected.status]}} · {{faNumber(selected.attempts!)}} attempts</p><p v-if="selected.next_attempt_at">Next attempt: {{faDate(selected.next_attempt_at)}}</p><p v-if="selected.error_code" class="hint-box">Review the previous delivery result or update the connection and policy.</p><button class="btn secondary" :disabled="busy||selecting" @click="select(selected,true)">Refresh and retain draft</button><button v-if="auth.can('notifications','update')" class="btn secondary" :disabled="busy||selecting" @click="dispatch">Check this notification's delivery</button><form v-if="mayRecover" class="form-grid" @submit.prevent="recover"><label class="field"><span>Notification recovery decision</span><select v-model="action" aria-label="Notification recovery decision" :disabled="busy"><option value="retry">Retry; an uncertain result may duplicate</option><option value="cancel">Cancel further delivery</option></select></label><label class="field"><span>Recovery reason</span><input v-model="reason" required minlength="3" maxlength="250" :disabled="busy" /></label><button class="btn" :disabled="busy||selecting||reason.trim().length<3">Record recovery decision</button></form><p v-if="auditError" class="message error" role="alert">{{auditError}}</p><p v-if="auditLoading">Loading history…</p><h3>Delivery attempts</h3><article v-for="row in attempts" :key="row.id"><p>{{faNumber(row.attempt)}} · {{outcomes[row.outcome]??'Needs review'}} · {{faDate(row.created_at)}}</p></article><div class="pager"><button :disabled="attemptPage<=1||auditLoading" @click="attemptPage--;audit()">‹</button><span>{{faNumber(attemptPage)}}</span><button :disabled="attemptPage>=attemptPages||auditLoading" @click="attemptPage++;audit()">›</button></div><h3>Staff decisions</h3><article v-for="row in history" :key="row.id"><p>{{row.action==='retry'?'Retry':'Cancel'}} · {{row.reason}} · {{faDate(row.created_at)}}</p></article><div class="pager"><button :disabled="historyPage<=1||auditLoading" @click="historyPage--;audit()">‹</button><span>{{faNumber(historyPage)}}</span><button :disabled="historyPage>=historyPages||auditLoading" @click="historyPage++;audit()">›</button></div></template></section></div>
<button v-if="mayCreate&&knownCustomer!==undefined" class="btn secondary" :disabled="busy" @click="startDraft">{{draftCustomer===undefined?'Create notification for customer '+faNumber(knownCustomer):'Continue notification draft for customer '+faNumber(draftCustomer)}}</button><Modal v-if="mayCreate&&draftCustomer!==undefined" v-model="createOpen" title="Create notification" :busy="busy" wide><p>For customer {{faNumber(draftCustomer)}}</p><p v-if="error" class="message error" role="alert">{{error}}</p><form class="form-grid" @submit.prevent="create"><label class="field"><span>Message title</span><input v-model="title" required :disabled="busy" /></label><label class="field"><span>Message body</span><textarea v-model="body" aria-label="Message body" required :disabled="busy" /><small>{{faNumber(messageSize)}} / {{faNumber(policy!.max_message_chars)}}</small></label><button class="btn" :disabled="busy||selecting||!validDraft">Create notification</button></form></Modal><p v-if="mayCreate&&knownCustomer===undefined" class="hint-box">Open a customer record or select a notification to retain the new message's recipient.</p></div></template>
<style scoped>.notification-body{white-space:pre-wrap;overflow-wrap:anywhere}.stack{min-width:0}textarea{min-height:130px}</style>
